def comps(pos, dirs):
 rem=set(pos); out=[]
 while rem:
  stack=[rem.pop()]; comp=set(stack)
  while stack:
   r,c=stack.pop()
   for dr,dc in dirs:
    p=(r+dr,c+dc)
    if p in rem: rem.remove(p);comp.add(p);stack.append(p)
